export const CUISINES = ['american','italian','latin','asian','mediterranean','indian','steakhouse','healthy'];

const DIETARY_FILTER_MAP = {
  meat_free:    s => s.dietaryTags.some(t => ['vegetarian','vegan'].includes(t)),
  dairy_free:   s => s.dietaryTags.includes('dairy-free'),
  gluten_free:  s => s.dietaryTags.includes('gluten-free'),
  thirty_min_max: s => s.prepTime <= 30,
  high_protein: s => !s.dietaryTags.includes('vegetarian') && !s.dietaryTags.includes('vegan'),
};

export function selectSeeds({ count, prefs = {}, excludeNames = [] }) {
  let pool = SEEDS.filter(s => !excludeNames.includes(s.name));

  // Hard dietary filters
  if (prefs.meat_free)      pool = pool.filter(DIETARY_FILTER_MAP.meat_free);
  if (prefs.dairy_free)     pool = pool.filter(DIETARY_FILTER_MAP.dairy_free);
  if (prefs.gluten_free)    pool = pool.filter(DIETARY_FILTER_MAP.gluten_free);
  if (prefs.thirty_min_max) pool = pool.filter(DIETARY_FILTER_MAP.thirty_min_max);
  if (prefs.high_protein)   pool = pool.filter(DIETARY_FILTER_MAP.high_protein);
  if (prefs.picky_eaters)   pool = pool.filter(s => s.difficulty <= 2);

  if (pool.length < count) {
    // Relax dietary filters except the hardest ones — just fall back to full pool minus exclude
    pool = SEEDS.filter(s => !excludeNames.includes(s.name));
    if (prefs.meat_free) pool = pool.filter(DIETARY_FILTER_MAP.meat_free);
  }

  // Cuisine rotation: spread across different cuisines
  const shuffled = [...pool].sort(() => 0.5 - Math.random());
  const selected = [];
  const usedCuisines = new Set();

  for (const seed of shuffled) {
    if (selected.length >= count) break;
    if (!usedCuisines.has(seed.cuisine)) {
      selected.push(seed);
      usedCuisines.add(seed.cuisine);
    }
  }
  // Fill remaining if cuisines ran out
  for (const seed of shuffled) {
    if (selected.length >= count) break;
    if (!selected.includes(seed)) selected.push(seed);
  }

  return selected.slice(0, count);
}
